pub struct Booking {
    pub start: u32,
    pub end: u32,
}

impl Booking {
    pub fn new(start: u32, end: u32) -> Self {
        Self { start, end }
    }
}

pub fn has_conflict(existing: &[Booking], candidate: Booking) -> bool {
    if candidate.start >= candidate.end {
        return false;
    }
    existing.iter().any(|b| b.start < b.end && candidate.start < b.end && b.start < candidate.end)
}

pub fn can_book(existing: &[Booking], candidate: Booking) -> bool {
    !has_conflict(existing, candidate)
}

